function validate([words]) {
  if (!Array.isArray(words) || words.length < 1 || words.length > 100) return 'words needs 1 to 100 strings.';
  if (!words.every(word => typeof word === 'string' && /^[a-z]{1,100}$/.test(word))) return 'Each word has 1 to 100 lowercase letters.';
  return null;
}

reference:
function firstPalindrome(words) {
  for (const word of words) {
    let left = 0;
    let right = word.length - 1;
    while (left < right && word[left] === word[right]) {
      left++;
      right--;
    }
    if (left >= right) {
      return word;
    }
  }
  return "";
}

brute:
function firstPalindrome(words) {
  const found = words.find(word => word === word.split('').reverse().join(''));
  return found === undefined ? '' : found;
}

generator:
function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const large = size === 'large';
  const letters = large ? 'abcdefghijklmnopqrstuvwxyz'.slice(0, int(1, 26)) : 'abc'.slice(0, int(1, 3));
  const randomWord = length => Array.from({ length }, () => letters[int(0, letters.length - 1)]).join('');
  const palindrome = length => {
    const half = randomWord(Math.floor(length / 2));
    const middle = length % 2 ? randomWord(1) : '';
    return half + middle + half.split('').reverse().join('');
  };
  // A palindrome with one letter changed (when that is possible) makes the pointers walk far before failing.
  const nearMiss = length => {
    const word = palindrome(length).split('');
    if (length > 1 && letters.length > 1) {
      const spot = int(0, Math.floor(length / 2) - 1);
      word[spot] = letters[(letters.indexOf(word[spot]) + 1) % letters.length];
    }
    return word.join('');
  };
  const count = large ? int(80, 100) : int(1, 6);
  const words = [];
  for (let i = 0; i < count; i++) {
    const length = large ? int(60, 100) : int(1, 5);
    const pick = rand();
    if (large) words.push(pick < 0.02 ? palindrome(length) : nearMiss(length));
    else words.push(pick < 0.3 ? palindrome(length) : pick < 0.6 ? nearMiss(length) : randomWord(length));
  }
  return [words];
}
